const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const needles = ee.Geometry.Point([-114.6141, 34.8481]).buffer(5000); // 5km buffer around Needles, CA
  const startDate = '2017-06-15';
  const endDate = '2017-06-22'; // exclusive, so covers through June 21

  // 2. Data Acquisition & Check
  let tempCollection = ee.ImageCollection('IDAHO_EPSCOR/GRIDMET')
    .filterDate(startDate, endDate)
    .select('tmmx'); // daily maximum air temperature in Kelvin

  const collSize = tempCollection.size().getInfo();
  if (collSize === 0) {
    console.log(`Images in date range: 0`);
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing
  const maxTempImage = tempCollection.max(); // pixel-wise max over the period
  const tempStats = maxTempImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: needles,
    scale: 4000, // GridMET native resolution ~4km
    maxPixels: 1e9,
    bestEffort: true,
  });
  const maxTempK = tempStats.get('tmmx').getInfo();

  // Check for valid pixels
  const countStats = maxTempImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: needles,
    scale: 4000,
    maxPixels: 1e9,
    bestEffort: true,
  });
  const pixelCount = countStats.get('tmmx').getInfo();

  if (pixelCount === 0) {
    console.log(`Images: ${collSize}, Valid pixels: 0`);
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation
  if (maxTempK === null || maxTempK === undefined) {
    console.log(`Images: ${collSize}, Result: null`);
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert Kelvin to Fahrenheit: F = (K - 273.15) * 9/5 + 32
  const maxTempF = (maxTempK - 273.15) * 9/5 + 32;

  // 5. Validation & Final Answer
  console.log(`Images: ${collSize}, Max temp: ${maxTempF.toFixed(1)}°F, Pixels: ${pixelCount}`);

  // Validate temperature range (sanity check: between -100°F and 200°F)
  if (maxTempF < -100 || maxTempF > 200) {
    console.log('<answer>C3</answer>');
  } else if (maxTempF >= 115) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
